[DataContractAttribute]
class ABSExcessObsoleteContract
{
    InventSiteId    siteId;
    TransDate       asOfDate;
    real            provisionPctSlow;
    real            provisionPctVerySlow;
    real            provisionPctDormant;
    real            provisionPctDead;
    boolean         deleteAndRegenerate;
    boolean         initialised;
}

Method.Source:
private void initDefaults()
{
    if (initialised) { return; }

    asOfDate             = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    provisionPctSlow     = 10;
    provisionPctVerySlow = 25;
    provisionPctDormant  = 50;
    provisionPctDead     = 100;
    deleteAndRegenerate  = true;
    initialised          = true;
}

[DataMemberAttribute('SiteId'),
 SysOperationLabelAttribute(literalStr("@ABS:ABSEOParmSite")),
 SysOperationDisplayOrderAttribute('1')]
public InventSiteId parmSiteId(InventSiteId _siteId = siteId)
{
    siteId = _siteId;
    return siteId;
}

[DataMemberAttribute('AsOfDate'),
 SysOperationLabelAttribute(literalStr("@ABS:ABSEOParmAsOfDate")),
 SysOperationDisplayOrderAttribute('2')]
public TransDate parmAsOfDate(TransDate _asOfDate = asOfDate)
{
    this.initDefaults();
    if (!prmIsDefault(_asOfDate))
    {
        asOfDate = _asOfDate;
    }
    return asOfDate;
}

[DataMemberAttribute('ProvisionPctSlow'),
 SysOperationLabelAttribute(literalStr("@ABS:ABSEOParmProvisionSlow")),
 SysOperationDisplayOrderAttribute('3')]
public real parmProvisionPctSlow(real _v = provisionPctSlow)
{
    this.initDefaults();
    if (!prmIsDefault(_v))
    {
        provisionPctSlow = _v;
    }
    return provisionPctSlow;
}

[DataMemberAttribute('ProvisionPctVerySlow'),
 SysOperationLabelAttribute(literalStr("@ABS:ABSEOParmProvisionVerySlow")),
 SysOperationDisplayOrderAttribute('4')]
public real parmProvisionPctVerySlow(real _v = provisionPctVerySlow)
{
    this.initDefaults();
    if (!prmIsDefault(_v))
    {
        provisionPctVerySlow = _v;
    }
    return provisionPctVerySlow;
}

[DataMemberAttribute('ProvisionPctDormant'),
