[DataMemberAttribute('ProvisionPctDead'),
 SysOperationLabelAttribute(literalStr("@ABS:ABSEOParmProvisionDead")),
 SysOperationDisplayOrderAttribute('6')]
public real parmProvisionPctDead(real _v = provisionPctDead)
{
    this.initDefaults();
    if (!prmIsDefault(_v))
    {
        provisionPctDead = _v;
