    return provisionPctDead;
}

[DataMemberAttribute('DeleteAndRegenerate'),
 SysOperationLabelAttribute(literalStr("@ABS:DeleteAndRegenerate")),
 SysOperationDisplayOrderAttribute('7')]
public boolean parmDeleteAndRegenerate(boolean _v = deleteAndRegenerate)
{
    this.initDefaults();
    if (!prmIsDefault(_v))
    {
        deleteAndRegenerate = _v;
    }
    return deleteAndRegenerate;
}
